ALTER TABLE student_exits ADD COLUMN client_request_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_student_exit_client_request ON student_exits(app_id,client_request_id) WHERE client_request_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS student_exit_exceptions (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',student_exit_id INTEGER NOT NULL,code TEXT NOT NULL CHECK(code IN ('overdue','failed_to_arrive','destination_unavailable','destination_refused','forgotten_checkin','incorrect_record','capacity_exceeded','simultaneous_limit')),severity TEXT NOT NULL DEFAULT 'warning' CHECK(severity IN ('information','warning','critical')),summary TEXT NOT NULL,evidence_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),raised_by TEXT NOT NULL,raised_at TEXT NOT NULL DEFAULT(datetime('now')),resolved_by TEXT,resolution TEXT,resolved_at TEXT,FOREIGN KEY(student_exit_id) REFERENCES student_exits(id));
CREATE UNIQUE INDEX IF NOT EXISTS uq_open_student_exit_exception ON student_exit_exceptions(app_id,student_exit_id,code) WHERE status='open';
CREATE TABLE IF NOT EXISTS student_exit_corrections (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',student_exit_id INTEGER NOT NULL,old_value_json TEXT NOT NULL,new_value_json TEXT NOT NULL,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(student_exit_id) REFERENCES student_exits(id));
CREATE TABLE IF NOT EXISTS student_exit_notification_rules (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',event_code TEXT NOT NULL,target_role TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'in_app' CHECK(channel IN ('in_app','email','sms')),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),updated_by TEXT,updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,event_code,target_role,channel));
CREATE TABLE IF NOT EXISTS student_exit_notification_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',student_exit_id INTEGER NOT NULL,event_code TEXT NOT NULL,target_role TEXT NOT NULL,channel TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','cancelled')),created_at TEXT NOT NULL DEFAULT(datetime('now')),published_at TEXT,FOREIGN KEY(student_exit_id) REFERENCES student_exits(id));
INSERT OR IGNORE INTO student_exit_notification_rules(app_id,event_code,target_role,channel) VALUES ('principal-ed','overdue','reception','in_app'),('principal-ed','failed_to_arrive','reception','in_app'),('principal-ed','failed_to_arrive','principal','in_app'),('principal-ed','campus_released','reception','in_app'),('principal-ed','exception_raised','principal','in_app');
